[crawl]
# West-wall duct: classic crawl height -- a duct should read tight. (Trialed at
# h=header; too open for a duct. Headers are for doorway soffits.)
1,22 dir=S len=5
# Doorway header over the wide double-door opening north of spawn -- the soffit
# hangs at h=header (taller than a duct slab); crouch through it like any drop.
15,16 dir=E len=2 h=header

[partitions]
22,22 -> 26,22  style=spotted height=low crawl=no
20,11 -> 20,14  style=spotted height=low crawl=no
# Cubicle test crosses (half-height): chevron + polka-dot side by side in the
# upper-right room, same row so both textures read at matched distance for LOD A/B.
# Chevron cross, center (25,13)
25,12 -> 25,14  style=chevron height=half crawl=no
24,13 -> 26,13  style=chevron height=half crawl=no
# Polka-dot cross, center (29,13)
29,12 -> 29,14  style=spotted height=half crawl=no
28,13 -> 30,13  style=spotted height=half crawl=no

[decals]
chair  9.5,15.5 face=E
chair  23.5,15.5 face=W
chair  6.5,11.5 face=S
chair  26.5,11.5 face=S
# Dark room (10,23)->(12,25): chairs waiting in the dark.
chair  10.5,23.5 face=S
chair  12.5,24.5 face=W
chair  11.5,25.5 face=N
# Dark room (1,1)->(3,3): a huddle in the corner gloom.
chair  1.5,1.5 face=S
chair  2.5,2.5 face=E
chair  3.5,3.5 face=N
# Scattered furnishing — the LOD makes these nearly free.
chair  19.5,8.5 face=W
chair  4.5,19.5 face=E
chair  21.5,26.5 face=N
chair  13.5,6.5 face=S
chair  28.5,22.5 face=W
