# corridor and the PVM is at the end of it, facing back at you (Mike's
# spot, HUD X:09.2 Y:19.5 A:000).
pvm    10.5,19.5 face=W
# THE CONSOLE (Mike's spot, 2026-08-10): desk-mounted (z=1), screen
# facing the open corridor to the east. Press A: the Master System
# boots on it.
pvm    13.6,20.3 face=E z=1
outlet 17,26.5 face=W z=0.2
door   16.5,31 face=S
neanderthal 16.3,23.5 face=S
